#include <bits/stdc++.h>using namespace std;using ll = long long; void solve() {    int n;    cin >> n;        vector<long long> a(n);    for (int i = 0; i < n; i++) {        cin >> a[i];    }        long long b_val;    for (int i = 0; i < n; i++) {        cin >> b_val;    }        if (n == 2) {        long long g = std::gcd(a[0], a[1]);        int ans = 0;        if (g < a[0]) ans++;        if (g < a[1]) ans++;        cout << ans << "\n";        return;    }        vector<long long> g(n - 1);    for (int i = 0; i < n - 1; i++) {        g[i] = std::gcd(a[i], a[i+1]);    }        int ans = 0;        if (g[0] < a[0]) ans++;        for (int i = 1; i < n - 1; i++) {        long long m = std::lcm(g[i-1], g[i]);        if (m < a[i]) {            ans++;        }    }        if (g[n-2] < a[n-1]) ans++;        cout << ans << "\n";} int main() {     int t;    cin >> t;    while (t--) {        solve();    }        return 0;}